        d = 2
    else:
        d = n  # default to n itself if no smaller divisor found
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                d = i
                break
    # Determine the largest proper divisor
    if d == n:
        return 1
    else:
        return n // d

