import math

def is_simple_power(x, n):
    """Check if x is a simple power of n."""
    if n == 0:
        return x == 0
    if x == 0:
        return False
    if n == 1:
        return x == 1
    if x == 1:
        return True
    if n > 0:
        k = math.log(x, n)
        k_rounded = round(k)
        return abs(n ** k_rounded - x) < 1e-10
    else:
        abs_n = abs(n)
        abs_x = abs(x)
        if abs_n == 1:
            return abs_x == 1
        if abs_x < 1e-10:
            return False
        k = math.log(abs_x, abs_n)
        k_rounded = round(k)
        if abs(abs_n ** k_rounded - abs_x) > 1e-10:
            return False
        return (k_rounded % 2 == 0) == (x > 0)

