    b_start, b_end = interval2
    start = max(a_start, b_start)
    end = min(a_end, b_end)
    if start > end:
        return "NO"
    length = end - start
    if length < 2:
        return "NO"
    for i in range(2, int(length ** 0.5) + 1):
        if length % i == 0:
            return "NO"
    return "YES"

