import heapq

def minPath(grid, k):
    N = len(grid)
    if N < 2:
        return []

    # Initialize best paths for each cell and path length
    best = [[[None] * (k + 1) for _ in range(N)] for _ in range(N)]
    heap = []

    # Initialize paths of length 1 for all cells
    for i in range(N):
        for j in range(N):
            path = [grid[i][j]]
            best[i][j][1] = path
            heapq.heappush(heap, (path, i, j))

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while heap:
        current_path, i, j = heapq.heappop(heap)
        current_m = len(current_path)

        if current_m == k:
            return current_path

        # Skip if this path is not the best known for (i,j) at current_m
        if current_path != best[i][j][current_m]:
            continue

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N:
                new_m = current_m + 1
                if new_m > k:
                    continue
                new_value = grid[ni][nj]
                new_path = current_path + [new_value]

                # Update best path if new path is better
                if new_path < best[ni][nj][new_m]:
                    best[ni][nj][new_m] = new_path
                    heapq.heappush(heap, (new_path, ni, nj))

    return []

